const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/custom_field_definitions',
  qs: {
    company_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    view: 'SOME_STRING_VALUE',
    tool_name: 'SOME_STRING_VALUE',
    includes_configurable_field_sets_count: 'SOME_BOOLEAN_VALUE',
    'filters[with_label]': 'SOME_STRING_VALUE',
    'scope[type]': 'SOME_STRING_VALUE',
    'scope[category]': 'SOME_STRING_VALUE',
    'scope[observations_category_id]': 'SOME_INTEGER_VALUE',
    'scope[inspection_type_id]': 'SOME_INTEGER_VALUE',
    'scope[generic_tool_id]': 'SOME_INTEGER_VALUE',
    'scope[action_plan_type_id]': 'SOME_INTEGER_VALUE',
    sort: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/custom_field_definitions?company_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&view=SOME_STRING_VALUE&tool_name=SOME_STRING_VALUE&includes_configurable_field_sets_count=SOME_BOOLEAN_VALUE&filters%5Bwith_label%5D=SOME_STRING_VALUE&scope%5Btype%5D=SOME_STRING_VALUE&scope%5Bcategory%5D=SOME_STRING_VALUE&scope%5Bobservations_category_id%5D=SOME_INTEGER_VALUE&scope%5Binspection_type_id%5D=SOME_INTEGER_VALUE&scope%5Bgeneric_tool_id%5D=SOME_INTEGER_VALUE&scope%5Baction_plan_type_id%5D=SOME_INTEGER_VALUE&sort=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

